/**
 * Two regions on one axis, resized by a draggable or keyboard-stepped divider (`design/components/split-pane.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/split-pane.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  scope,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/layout/split-pane.module.css'

export type SplitPaneOrientation = NonNullable<SplitPaneProps['orientation']>

export interface SplitPaneProps {
  defaultRatio?: number
  /**
   * The second pane.
   */
  end: JSX.Element
  endMin?: number
  /**
   * The separator's accessible name, such as "Resize navigator" rather than "Divider".
   */
  label: string
  /**
   * Fires on release and after each keyboard step, like Slider's `onCommit`, so apps can persist
   * the layout without debouncing `onRatioChange`.
   */
  onCommit?: (ratio: number) => void
  onRatioChange?: (ratio: number) => void
  /**
   * The axis of the panes; `horizontal` means side by side, as in Stepper.
   */
  orientation?: 'horizontal' | 'vertical'
  /**
   * The start pane's share, 0–1, controlled like Slider's value.
   */
  ratio?: number
  /**
   * The first pane in reading order: inline-start, or block-start when stacked.
   */
  start: JSX.Element
  /**
   * Content floors in px, drawn by `minmax()` and respected by the keyboard clamp.
   */
  startMin?: number
}

/** Two regions on one axis, resized by a draggable or keyboard-stepped divider. */
export default function SplitPane(given: SplitPaneProps): JSX.Element {
  const props = mergeProps(
    { orientation: 'horizontal', defaultRatio: 0.5, startMin: 0, endMin: 0 } as Defaults<
      SplitPaneProps,
      'orientation' | 'defaultRatio' | 'startMin' | 'endMin'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const divider = elementRef<HTMLElement>()
    const root = elementRef<HTMLElement>()
    const mirror = createCell(Math.min(1, Math.max(0, props.defaultRatio)))
    const dragging = createCell(false)
    const bounds = createCell({ min: 0, max: 1 })
    const latest = createCell(Math.min(1, Math.max(0, props.ratio ?? props.defaultRatio)))
    const horizontal = createDerived(() => props.orientation === 'horizontal')
    const current = createDerived(() => Math.min(1, Math.max(0, props.ratio ?? mirror.value)))
    const clamp = createDerived(
      () => (value: number) => Math.min(bounds.value.max, Math.max(bounds.value.min, value)),
    )
    const effective = createDerived(() => clamp.value(current.value))
    const startId = createDerived(() => `${uid}-start`)
    const move = createDerived(() => (next: number) => {
      const clamped = Math.round(clamp.value(Math.min(1, Math.max(0, next))) * 10000) / 10000
      if (clamped === latest.value) return
      latest.value = clamped
      mirror.value = clamped
      props.onRatioChange?.(clamped)
    })
    const measure = createDerived(() => () => {
      if (root.value === null) return
      const box = root.value.getBoundingClientRect()
      const line = divider.value?.getBoundingClientRect()
      const usable =
        (horizontal.value ? box.width : box.height) -
        (line === undefined ? 0 : horizontal.value ? line.width : line.height)
      if (usable <= 0 || props.startMin + props.endMin >= usable) {
        bounds.value = { min: 0, max: 1 }
        return
      }
      bounds.value = {
        min: Math.min(1, Math.max(0, props.startMin / usable)),
        max: Math.min(1, Math.max(0, 1 - props.endMin / usable)),
      }
    })
    const pointerDown = createDerived(() => (event: PointerEvent) => {
      try {
        ;(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId)
      } catch {
        /* an inactive pointer: nothing to capture */
      }
      dragging.value = true
    })
    const pointerMove = createDerived(() => (event: PointerEvent) => {
      if (!dragging.value || root.value === null) return
      const box = root.value.getBoundingClientRect()
      const handle = (event.currentTarget as HTMLElement).getBoundingClientRect()
      const thickness = horizontal.value ? handle.width : handle.height
      const usable = (horizontal.value ? box.width : box.height) - thickness
      if (usable <= 0) return
      const rtl = horizontal.value && getComputedStyle(root.value).direction === 'rtl'
      const along = horizontal.value
        ? rtl
          ? box.right - event.clientX
          : event.clientX - box.left
        : event.clientY - box.top
      move.value((along - thickness / 2) / usable)
    })
    const pointerUp = createDerived(() => (event: PointerEvent) => {
      if (!dragging.value) return
      const target = event.currentTarget as HTMLElement
      if (target.hasPointerCapture(event.pointerId)) target.releasePointerCapture(event.pointerId)
      dragging.value = false
      props.onCommit?.(latest.value)
    })
    const keyDown = createDerived(() => (event: KeyboardEvent) => {
      const rtl =
        horizontal.value && getComputedStyle(event.currentTarget as HTMLElement).direction === 'rtl'
      const grow = horizontal.value ? (rtl ? 'ArrowLeft' : 'ArrowRight') : 'ArrowDown'
      const shrink = horizontal.value ? (rtl ? 'ArrowRight' : 'ArrowLeft') : 'ArrowUp'
      let next: number
      switch (event.key) {
        case grow:
          next = current.value + 0.02
          break
        case shrink:
          next = current.value - 0.02
          break
        case 'PageUp':
          next = current.value + 0.1
          break
        case 'PageDown':
          next = current.value - 0.1
          break
        case 'Home':
          next = bounds.value.min
          break
        case 'End':
          next = bounds.value.max
          break
        default:
          return
      }
      event.preventDefault()
      move.value(next)
      props.onCommit?.(latest.value)
    })
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const run = () => {
        measure.value()
      }
      const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
      for (const element of [root.value]) if (element) resize?.observe(element)
      release1 = () => {
        resize?.disconnect()
      }
      run()
    }
    watchEffect(
      createMemo(() => [props.orientation, props.startMin, props.endMin]),
      effect1,
      true,
    )
    onCleanup(() => release1?.())
    const effect2 = () => {
      latest.value = current.value
    }
    watchEffect(
      createMemo(() => current.value),
      effect2,
      false,
    )
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const ran = agentMember({
        member: 'SplitPane',
        element: () => divider.value,
        state: () => ({ position: Math.round(effective.value * 100) }),
        actions: {
          set: {
            argument: 'number',
            run: (value) =>
              (() => {
                move.value(value / 100)
                props.onCommit?.(latest.value)
              })(),
          },
        },
      })
      release3 = () => {
        ran()
      }
    }
    onMount(effect3)
    onCleanup(() => release3?.())
    return (
      <div
        class={styles.root}
        style={{
          '--pm-split-start': `${effective.value}fr`,
          '--pm-split-end': `${1 - effective.value}fr`,
          '--pm-split-start-min': `${props.startMin}px`,
          '--pm-split-end-min': `${props.endMin}px`,
        }}
        data-orientation={props.orientation}
        data-member="split-pane"
        ref={root.attach}
      >
        {/* start */}
        <div class={styles.pane} id={startId.value}>
          {props.start}
        </div>
        {/* divider */}
        <div
          class={styles.divider}
          data-split-pane-part="divider"
          role="separator"
          tabindex="0"
          aria-label={props.label}
          aria-orientation={horizontal.value ? 'vertical' : 'horizontal'}
          aria-controls={startId.value}
          aria-valuenow={Math.round(effective.value * 100)}
          aria-valuemin={Math.round(bounds.value.min * 100)}
          aria-valuemax={Math.round(bounds.value.max * 100)}
          data-state={dragging.value ? 'dragging' : undefined}
          onpointerdown={($event: PointerEvent) => pointerDown.value($event)}
          onpointermove={($event: PointerEvent) => pointerMove.value($event)}
          onpointerup={($event: PointerEvent) => pointerUp.value($event)}
          onpointercancel={($event: PointerEvent) => pointerUp.value($event)}
          onkeydown={($event: KeyboardEvent) => keyDown.value($event)}
          ref={divider.attach}
        />
        {/* end */}
        <div class={styles.pane}>{props.end}</div>
      </div>
    )
  })
}
